const names={'两种都要':'全部场景','纯商品展示场景':'商品展示','人机交互场景':'人物互动'};
const closeAll=()=>document.querySelectorAll('.param-picker').forEach(p=>{p.querySelector('.param-menu').hidden=true;p.querySelector('.param-trigger').setAttribute('aria-expanded','false');});
for(const id of ['ratio','scene','count']){
 const select=document.getElementById(id),wrap=document.createElement('div');wrap.className='param-picker';wrap.dataset.param=id;select.before(wrap);wrap.append(select);select.hidden=true;
 const trigger=document.createElement('button');trigger.type='button';trigger.className='param-trigger';trigger.setAttribute('aria-label',select.getAttribute('aria-label'));trigger.setAttribute('aria-haspopup','listbox');trigger.setAttribute('aria-expanded','false');
 const menu=document.createElement('div');menu.className='param-menu';menu.id=id+'-menu';menu.setAttribute('role','listbox');menu.setAttribute('aria-label',select.getAttribute('aria-label'));menu.hidden=true;trigger.setAttribute('aria-controls',menu.id);wrap.append(trigger,menu);
 const update=()=>{trigger.textContent=(names[select.value]||select.selectedOptions[0].textContent)+' ⌄';trigger.disabled=select.disabled;menu.querySelectorAll('button').forEach((b,i)=>{b.setAttribute('aria-selected',String(select.selectedIndex===i));b.querySelector('.check').textContent=select.selectedIndex===i?'✓':'';});if(select.disabled)closeAll();};
 Array.from(select.options).forEach((option,i)=>{const b=document.createElement('button');b.type='button';b.className='param-option';b.setAttribute('role','option');if(id==='ratio'){const icon=document.createElement('span');icon.className='ratio-icon';const [w,h]=option.value.split(':').map(Number);icon.style.width=(18*w/Math.max(w,h))+'px';icon.style.height=(18*h/Math.max(w,h))+'px';b.append(icon);}const label=document.createElement('span');label.textContent=names[option.value]||option.textContent;const check=document.createElement('span');check.className='check';b.append(label,check);b.onclick=()=>{select.selectedIndex=i;select.dispatchEvent(new Event('change',{bubbles:true}));update();closeAll();trigger.focus();};menu.append(b);});
 trigger.onclick=()=>{const opening=menu.hidden;closeAll();menu.hidden=!opening;trigger.setAttribute('aria-expanded',String(opening));if(opening)menu.querySelector('[aria-selected="true"]').focus();};
 menu.onkeydown=e=>{const options=Array.from(menu.children),index=options.indexOf(document.activeElement);if(['ArrowDown','ArrowUp','Home','End'].includes(e.key)){e.preventDefault();const next=e.key==='Home'?0:e.key==='End'?options.length-1:(index+(e.key==='ArrowDown'?1:-1)+options.length)%options.length;options[next].focus();}};
 select.addEventListener('change',update);new MutationObserver(update).observe(select,{attributes:true,attributeFilter:['disabled']});update();
}
document.addEventListener('click',e=>{if(!e.target.closest('.param-picker'))closeAll();});document.addEventListener('keydown',e=>{if(e.key==='Escape'){const open=document.querySelector('.param-trigger[aria-expanded="true"]');closeAll();open?.focus();}});
const brief=document.getElementById('brief'),prompts=['把香水放在晨光里的梳妆台上','让模特在商场里试涂这支口红','给这只腕表拍一张咖啡馆氛围照','为这款商品设计简洁的高级感背景'];let index=0;brief.placeholder=prompts[0];setInterval(()=>{if(document.hidden||brief.value||document.activeElement===brief)return;brief.placeholder=prompts[++index%prompts.length];brief.classList.remove('prompt-change');void brief.offsetWidth;brief.classList.add('prompt-change');},5000);
